@app.get("/orders")
def orders():
    customer = request.args["customer"]
    rows = db.execute(f"SELECT id, total FROM orders WHERE customer = '{customer}'").fetchall()
    return {"orders": rows}


@app.post("/thumbnail")
def thumbnail():
    name = request.form["file"]
    subprocess.run(f"convert uploads/{name} -resize 200x200 thumbs/{name}", shell=True, check=True)
    return {"ok": True}


@app.post("/import")
def import_url():
    url = request.json["url"]
    data = requests.get(url, verify=False).content
    return {"bytes": len(data)}

