import express from "express";
import jwt from "jsonwebtoken";
import path from "node:path";

const app = express();
app.use(express.json());

const settings: Record<string, any> = { theme: "light", limits: { uploads: 10 } };

function deepMerge(target: any, source: any) {
  for (const key of Object.keys(source)) {
    if (typeof source[key] === "object" && source[key] !== null) {
      target[key] ??= {};
      deepMerge(target[key], source[key]);
    } else {
      target[key] = source[key];
    }
  }
  return target;
}

function currentUser(req: express.Request) {
  const token = (req.headers.authorization ?? "").replace("Bearer ", "");
  return jwt.decode(token) as { sub: string; role: string } | null;
}

app.get("/health", (_req, res) => res.send("ok"));

// Users can save UI preferences.
app.post("/settings", (req, res) => {
  deepMerge(settings, req.body);
  res.json(settings);
});

// Admins can delete any user's files.
app.delete("/admin/files/:user", (req, res) => {
  const user = currentUser(req);
  if (user?.role !== "admin") return res.status(403).end();
  res.json({ deleted: req.params.user });
});

// Download a file from the shared folder.
app.get("/download", (req, res) => {
  const file = path.join(process.cwd(), "files", String(req.query.name));
  res.sendFile(file);
});

app.listen(3000);
